          k_inn: { need: ['!f_inn'], a: ['네, 소양여관이요. 여관에서 자 본 건 그때가 처음이었어요. 잠이 안 와서 새벽까지 천장만 봤어요.'], else: ['여관이요? 제가 무슨 돈이 있어서요.'] },
          k_ilsubook: { need: ['!f_inn'], a: [{ p: '…아침에 아궁이 재를 치웠어요. 재 속에 타다 만 비닐 쪼가리가 있었는데 수첩 표지 같았어요. 파란 비닐에 "대원" 도장 반쪽.', f: 'f_ashbook' }, '사장님이 보시더니 재를 그냥 강에 버리라고 하셨어요.'], else: ['수첩이요? 무슨 수첩이요. 몰라요.'] },
          k_luminol: ['그 바닥요? 이튿날 아침에 가 보니 물청소가 돼 있었어요. 사장님이 옻을 엎질러서 닦았다고… 양잿물 냄새가 코를 찔렀어요.'],
          k_bloodtype: ['저 O형이에요. 군대 신검 받을 때 알았어요. …왜요?', '손을 크게 벤 적이요? 없어요. 끌은 사장님이 무섭게 가르쳐서, 저는 한 번도 안 다쳤어요.'],
          k_saw: ['공방 톱이요? 벽에 큰 양날톱이 하나 걸려 있었어요. 사장님 아버지 때부터 쓰던 거요. 그 주에 새 톱으로 바뀌어 있더라고요. 헌 톱은 날이 나갔다고.'],
          k_jimknot: ['짐 매듭요? 사장님이 자개장 실을 때 꼭 그렇게 묶으세요. 줄 가운데 고를 틀어서 걸고 당기는 거요. 저도 그걸 제일 먼저 배웠어요.'],
          k_truck: ['용달요? …그날 새벽 네 시에 용달이 오기로 돼 있었어요. 자개장 열두 짝 싣고 서울로 간다고. 근데 아침에 가 보니 자개장이 그대로 있었어요.'],
          k_ham: ['사장님은… 무서운 분이에요. 말을 안 하세요. 그 일 있고 나서는 더 안 하셨어요.'],
          k_cheonghak: ['자개 공방이에요. 열일곱에 들어가서 삼 년 있었어요. 형들은 다 떠나고 저만 남았죠.'],
          k_pyeon: ['수금원 아저씨요? 한 달에 몇 번 공방에 왔어요. 사장님이랑 뒷방에서 얘기하고 나면 사장님 얼굴이 하얘졌어요.'],
