          k_night: { need: ['!f_inn'], a: ['…용수를 여관에 보낸 건 맞소. 짐을 싸려고. 빚쟁이들 몰래 새벽에 뜨려고 했소. 그게 죄요?', '그런데 안 떴소. 마음이 바뀌었지.'], else: ['일찍 잤소. 용수 놈도 다락에 있었고.'] },
          k_saw: { need: ['!f_hardware'], a: ['…헌 톱은 날이 나가서 버렸소. 새 톱 사는 게 죄요?', '— 토요일 아침 여덟 시 반에요? 철물점 문 열자마자?', '(대답하지 않는다)'], else: ['톱? 공방에 톱 없는 데가 어디 있소. 아버지 때부터 쓰던 양날톱 하나로 다 했소.'] },
          k_luminol: { need: ['!f_lumi_type'], a: ['그 바닥 피는 용수 놈이 끌에 손을 베였을 때 흘린 거요. 공방에서 손 안 베는 날이 없소.'], else: ['루미놀? 그런 건 모르오. 공방 바닥에 옻이며 아교며 온갖 게 다 스몄소.'] },
          k_truck: { need: ['!f_truck'], a: ['…용달을 부른 것도 맞고 취소한 것도 맞소. 새벽 세 시에. 마음이 바뀌었다니까.'], else: ['용달? 가구 하는 사람이 용달 부르는 게 이상하오?'] },
          k_ledger: ['대원상사 돈을 쓴 건 맞소. 이백오십. 자개장 대목 믿고 빌렸는데 대목이 안 왔지.'],
